import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    adj = [[] for _ in range(n + 1)]
    rev_adj = [[] for _ in range(n + 1)]

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        rev_adj[v].append(u)

    k = int(next(iterator))
    p = []
    for _ in range(k):
        p.append(int(next(iterator)))

    s = p[0]
    t = p[-1]

    dist = [-1] * (n + 1)
    dist[t] = 0
    queue = deque([t])

    while queue:
        u = queue.popleft()
        d = dist[u]
        for v in rev_adj[u]:
            if dist[v] == -1:
                dist[v] = d + 1
                queue.append(v)

    min_rebuilds = 0
    max_rebuilds = 0

    for i in range(k - 1):
        curr = p[i]
        nxt = p[i + 1]

        if dist[curr] == -1 or dist[nxt] == -1:
            continue

        if dist[nxt] != dist[curr] - 1:
            min_rebuilds += 1
            max_rebuilds += 1
        else:
            on_shortest_path = False
            for neighbor in adj[curr]:
                if dist[neighbor] == dist[curr] - 1:
                    if neighbor == nxt:
                        on_shortest_path = True
                    else:
                        break
            if not on_shortest_path:
                min_rebuilds += 1
            else:
                has_other_shortest = False
                for neighbor in adj[curr]:
                    if dist[neighbor] == dist[curr] - 1 and neighbor != nxt:
                        has_other_shortest = True
                        break
                if has_other_shortest:
                    max_rebuilds += 1

    print(f"{min_rebuilds} {max_rebuilds}")

if __name__ == "__main__":
    solve()
